<script>
/* ================= EMBEDDED ASSETS ================= */
const GM = {
  "pwa-signin": "data:image/jpeg;base64,",
  "pwa-dashboard": "data:image/jpeg;base64,",
  "pwa-dashboard-menu": "data:image/jpeg;base64,",
  "pwa-myplan": "data:image/jpeg;base64,",
  "pwa-packages": "data:image/jpeg;base64,",
  "pwa-wallet": "data:image/jpeg;base64,",
  "pwa-wallet2": "data:image/jpeg;base64,",
  "pwa-support": "data:image/jpeg;base64,",
  "pwa-notifications": "data:image/jpeg;base64,",
  "pwa-rafer": "data:image/jpeg;base64,",
  "pwa-activity": "data:image/jpeg;base64,",
  "pwa-withdraw-live": "data:image/jpeg;base64,",
  "pwa-bonus": "data:image/jpeg;base64,",
  "pwa-settings": "data:image/jpeg;base64,",
  "admin-dashboard": "data:image/jpeg;base64,",
  "admin-stats": "data:image/jpeg;base64,",
  "admin-website-customizer": "data:image/jpeg;base64,",
  "admin-panel-customizer": "data:image/jpeg;base64,",
  "admin-investors": "data:image/jpeg;base64,",
  "admin-packages": "data:image/jpeg;base64,",
  "admin-customer": "data:image/jpeg;base64,",
  "site-homepage": "data:image/jpeg;base64,"
};

/* assign embedded images */
document.querySelectorAll('img[data-gm]').forEach(im=>{
  const k=im.getAttribute('data-gm');
  if(GM[k]&&!im.getAttribute('src')) im.src=GM[k];
});

/* ================= NAV / PROGRESS ================= */
const nav=document.getElementById('nav'),bar=document.getElementById('bar'),topBtn=document.getElementById('top-btn');
addEventListener('scroll',()=>{
  const y=scrollY,h=document.documentElement.scrollHeight-innerHeight;
  bar.style.width=(y/h*100)+'%';
  nav.classList.toggle('scrolled',y>40);
  topBtn.classList.toggle('show',y>700);
  /* hero scroll parallax */
  document.querySelectorAll('[data-spx]').forEach(el=>{
    el.style.translate='0 '+(y*parseFloat(el.dataset.spx)*0.5)+'px';
  });
  const st=document.getElementById('stage');
  if(st&&y<innerHeight) st.style.translate='0 '+(y*0.12)+'px';
},{passive:true});
topBtn.onclick=()=>scrollTo({top:0,behavior:'smooth'});

/* active link */
const secs=[...document.querySelectorAll('section.blk,header.hero')];
const links=[...document.querySelectorAll('.nl')];
addEventListener('scroll',()=>{
  let cur='';
  secs.forEach(s=>{if(scrollY>=s.offsetTop-140)cur=s.id;});
  links.forEach(a=>a.classList.toggle('on',a.getAttribute('href')==='#'+cur));
},{passive:true});

/* ================= REVEAL ================= */
const io=new IntersectionObserver(es=>es.forEach(e=>{
  if(e.isIntersecting){e.target.classList.add('on');io.unobserve(e.target);}
}),{threshold:.06});
document.querySelectorAll('.rv,.step').forEach(el=>io.observe(el));

/* ================= COUNTERS ================= */
const cio=new IntersectionObserver(es=>es.forEach(e=>{
  if(!e.isIntersecting)return;
  const el=e.target,t=+el.dataset.count,suf=el.dataset.suffix||'',raw=el.dataset.raw;
  if(raw){el.textContent=raw;cio.unobserve(el);return;}
  const t0=performance.now(),D=1600;
  const tick=n=>{const p=Math.min((n-t0)/D,1),v=Math.round(t*(1-Math.pow(1-p,3)));
    el.textContent=v+suf;if(p<1)requestAnimationFrame(tick);};
  requestAnimationFrame(tick);cio.unobserve(el);
}),{threshold:.6});
document.querySelectorAll('[data-count]').forEach(el=>cio.observe(el));

/* ================= HERO 3D PARALLAX (mouse) ================= */
const stage=document.getElementById('stage');
if(matchMedia('(pointer:fine)').matches&&stage){
  const hero=document.querySelector('.hero');
  let rx=0,ry=0,cx=0,cy=0,raf=null;
  hero.addEventListener('mousemove',e=>{
    const r=hero.getBoundingClientRect();
    cx=(e.clientX-r.left)/r.width-.5; cy=(e.clientY-r.top)/r.height-.5;
    if(!raf)raf=requestAnimationFrame(upd);
  });
  hero.addEventListener('mouseleave',()=>{cx=0;cy=0;if(!raf)raf=requestAnimationFrame(upd);});
  function upd(){
    raf=null;
    stage.querySelectorAll('.dev,[data-depth]').forEach(el=>{
      const d=parseFloat(el.dataset.depth||14);
      const rot=el.classList.contains('lap')?' rotateY(9deg) rotateX(4deg) rotate(-4deg)':
                el.classList.contains('p1')?' rotate(7deg) rotateY(-10deg)':
                el.classList.contains('p2')?' rotate(-9deg) rotateY(12deg)':'';
      el.style.transform=`translate3d(${(-cx*d).toFixed(1)}px,${(-cy*d).toFixed(1)}px,0)${rot}`;
    });
  }
}

/* ================= TILT CARDS ================= */
if(matchMedia('(pointer:fine)').matches){
  document.querySelectorAll('.tilt').forEach(c=>{
    c.addEventListener('mousemove',e=>{
      const r=c.getBoundingClientRect();
      const x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;
      c.style.transform=`perspective(900px) rotateY(${x*9}deg) rotateX(${-y*9}deg) translateY(-4px)`;
    });
    c.addEventListener('mouseleave',()=>c.style.transform='');
  });
}

/* ================= ADMIN GALLERY ================= */
const admShots=[
  ['admin-dashboard','Live Dashboard'],['admin-stats','Platform Stats'],
  ['admin-investors','Investor Manager'],['admin-packages','Package Manager'],
  ['admin-customer','KYC & Customer View'],['admin-website-customizer','Website Customizer'],
  ['admin-panel-customizer','Panel Customizer']
];
const admTh=document.getElementById('admThumbs');
[...admTh.children].forEach((d,i)=>{
  const [k,label]=admShots[i];
  d.onclick=()=>{
    document.querySelectorAll('#admThumbs .thumb').forEach(x=>x.classList.remove('on'));
    d.classList.add('on');
    const m=document.getElementById('admMain');m.style.opacity=0;
    setTimeout(()=>{m.src=GM[k];m.style.opacity=1;},180);
  };
});
document.getElementById('admMain').style.transition='opacity .25s';

/* ================= PWA GALLERY ================= */
const pwaShots=[
  ['pwa-dashboard','Dashboard'],['pwa-signin','Sign In'],['pwa-myplan','My Plan'],['pwa-packages','Packages'],
  ['pwa-wallet','Wallet'],['pwa-wallet2','Add Funds'],['pwa-notifications','Notifications'],['pwa-rafer','Referral'],
  ['pwa-support','Support'],['pwa-bonus','Bonus History'],['pwa-withdraw-live','Withdraw Live'],['pwa-activity','Activity Log'],
  ['pwa-settings','Theme Settings'],['pwa-dashboard-menu','Side Menu']
];
const pwaTh=document.getElementById('pwaThumbs');
const phC=document.getElementById('phCimg'),phL=document.getElementById('phLimg'),phR=document.getElementById('phRimg');
const phLe=document.getElementById('phL'),phRe=document.getElementById('phR');
let cIdx=0;
/* noop */
function setStage(k){
  phC.style.opacity=0;
  setTimeout(()=>{phC.src=GM[k];phC.style.opacity=1;},180);
}
phC.parentElement.parentElement.style /* noop */
document.getElementById('phC').style.transition='opacity .25s';
phC.style.transition='opacity .25s';phL.style.transition='opacity .25s';phR.style.transition='opacity .25s';
[...pwaTh.children].forEach((d,i)=>{
  const [k]=pwaShots[i];
  d.onclick=()=>{
    cIdx=i;
    document.querySelectorAll('#pwaThumbs .thumb').forEach(x=>x.classList.remove('on'));
    d.classList.add('on');
    setStage(k);
    phL.src=GM[pwaShots[(i-1+pwaShots.length)%pwaShots.length][0]];
    phR.src=GM[pwaShots[(i+1)%pwaShots.length][0]];
  };
});
phLe.onclick=()=>pwaTh.children[(cIdx-1+pwaShots.length)%pwaShots.length].click();
phRe.onclick=()=>pwaTh.children[(cIdx+1)%pwaShots.length].click();
</script>
</body>
</html>

